import{_ as a,o as t,c as i,ag as s}from"./chunks/framework.CPvOxTBX.js";const u=JSON.parse('{"title":"Cloud sync","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cloud-sync.md","filePath":"guide/cloud-sync.md","lastUpdated":1793368961000}'),o={name:"guide/cloud-sync.md"};function n(r,e,d,c,l,h){return t(),i("div",null,e[0]||(e[0]=[s('<h1 id="cloud-sync" tabindex="-1">Cloud sync <a class="header-anchor" href="#cloud-sync" aria-label="Permalink to &quot;Cloud sync&quot;">​</a></h1><p>Ciyue can merge your wordbook, tags, flashcards, and review history through a remote file store. The first connection shows a read-only preview; nothing is written until you confirm. Dictionaries are listed separately and are transferred only when you select them.</p><p>Credentials are stored in the platform secure storage, not in app preferences. Ciyue does not provide a hosted sync service. WebDAV, SFTP, and S3-compatible connections use open protocols and do not require a Ciyue account.</p><h2 id="webdav" tabindex="-1">WebDAV <a class="header-anchor" href="#webdav" aria-label="Permalink to &quot;WebDAV&quot;">​</a></h2><p>Enter the server URL, remote folder, and optional username/password. Use HTTPS whenever the server is not on the local machine. WebDAV works with services such as Nextcloud, ownCloud, and NAS servers that expose WebDAV.</p><h2 id="sftp" tabindex="-1">SFTP <a class="header-anchor" href="#sftp" aria-label="Permalink to &quot;SFTP&quot;">​</a></h2><p>Enter an <code>sftp://</code> URL, such as <code>sftp://nas.example.net:22/backups</code>. The URL path is a base directory; when omitted, Ciyue uses the SFTP account&#39;s home directory. Enter the username and either a password, an SSH private-key file, or both. An optional passphrase unlocks an encrypted private key.</p><p>Ciyue requires a pinned SSH host-key fingerprint and will reject a missing or different fingerprint. Obtain the SHA-256 fingerprint from your server administrator through a trusted channel. For an OpenSSH server, this command prints a fingerprint that can be compared with the administrator&#39;s value:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keyscan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nas.example.net</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span></span></code></pre></div><p>Copy the <code>SHA256:...</code> value into Ciyue. <code>ssh-keyscan</code> alone does not authenticate the server, so do not trust its output without independently verifying it. If your server uses a different host-key algorithm, specify that algorithm instead of <code>ed25519</code>. A changed host key (for example, after server replacement) requires updating the saved fingerprint.</p><h2 id="s3-compatible-storage" tabindex="-1">S3-compatible storage <a class="header-anchor" href="#s3-compatible-storage" aria-label="Permalink to &quot;S3-compatible storage&quot;">​</a></h2><p>Enter the HTTPS endpoint, bucket, region, access key ID, and secret access key. The remote folder is used as a prefix inside the bucket, so Ciyue lists only that prefix rather than scanning unrelated bucket objects. For example:</p><ul><li>MinIO: use the server&#39;s endpoint and region; path-style addressing is commonly enabled.</li><li>Cloudflare R2: use the account endpoint, region <code>auto</code>, and usually disable path-style addressing.</li><li>AWS S3: use <code>https://s3.&lt;region&gt;.amazonaws.com</code>, the matching region, and disable path-style addressing.</li></ul><p>The addressing mode depends on the provider; if connection tests fail, check the provider&#39;s endpoint and bucket-addressing requirements. Plain HTTP is accepted only for loopback development endpoints such as <code>http://127.0.0.1:9000</code>. Use credentials scoped to the chosen bucket and the minimum permissions needed to list, read, write, copy, and delete Ciyue sync objects.</p><h2 id="sync-behavior" tabindex="-1">Sync behavior <a class="header-anchor" href="#sync-behavior" aria-label="Permalink to &quot;Sync behavior&quot;">​</a></h2><p>Ciyue stores versioned sync records and merges changes from each device. Concurrent edits and deletions are preserved as conflicts rather than silently overwriting one another. A preview does not create directories, upload data, or modify the remote store. Confirming the preview begins the sync.</p><p>Dictionary files are not included by default. Select each dictionary explicitly in the preview. Downloads are checked before being added to the local dictionary library and are not automatically enabled.</p><h2 id="which-files-travel-with-a-dictionary" tabindex="-1">Which files travel with a dictionary <a class="header-anchor" href="#which-files-travel-with-a-dictionary" aria-label="Permalink to &quot;Which files travel with a dictionary&quot;">​</a></h2><p>An MDX dictionary travels with its <code>.mdd</code> resources, any adjacent <code>.css</code> and <code>.js</code>, and the custom font configured for it.</p><p>A StarDict dictionary travels with its <code>.ifo</code>, its index and body (<code>.idx</code> or <code>.idx.gz</code>, <code>.dict</code> or <code>.dict.dz</code>), an optional synonym index (<code>.syn</code>, <code>.syn.gz</code>, or <code>.syn.dz</code>), and a resource archive in any of the places Ciyue reads: <code>res.zip</code>, <code>&lt;name&gt;.res.zip</code>, or <code>res/res.zip</code>.</p><p>A <code>res/</code> folder travels as well, but only while it stays small — up to 100 files and 20 MB. Beyond that the folder is left out and the rest of the dictionary still syncs. Resources are uploaded one file at a time, so a folder holding thousands of them would make the transfer slow and push the dictionary past the file limit Ciyue accepts for a package. If your dictionary keeps many images or audio files loose in <code>res/</code>, pack them into <code>res.zip</code> instead: Ciyue reads the archive directly, so one file replaces thousands of individual ones.</p>',21)]))}const y=a(o,[["render",n]]);export{u as __pageData,y as default};
